/*
 * --------------------------------------------------
 * 主题：【简约灰白】冬枝凝雪
 * 作者：gfqw
 * 感谢：墨千尾老师的拼好码基础框架 和 lc美化贴老师们的教程
 * --------------------------------------------------
 */

/* ✍🏻引入字体：Huiwen-mincho */
@import url("https://fontsapi.zeoseven.com/256/main/result.css");

/* ========================================================= */
/* 🛠️ 全局调整 (请在这里修改数值来调整布局) 🛠️ */
/* ========================================================= */
:root {
  /* --- 1. 消息框卡片与背景透明度 --- */
  --mes-margin-top: 20px;      
  --char-card-opacity: 75%;    
  --user-card-opacity: 75%;    
  --card-blur: 5px;            
  --ui-panel-bg: color-mix(in srgb, var(--SmartThemeBlurTintColor) 90%, transparent);

  /* --- 2. 顶部大图片 Banner --- */
  --user-big-image: url('https://i.postimg.cc/LX3WJGmW/dong②.jpg'); 
  --char-big-image: url('https://i.postimg.cc/ydyGD272/dong①.jpg'); 
  --banner-height: 200px;      

  /* --- 3. 头像与文艺句子设定 --- */
  --avatar-size: 90px;         
  --quote-font-size: 13px;     
  --user-quote-text: "「 雪与雾将世界缓缓埋葬… 」"; 
  --char-quote-text: "「 雪落时，世界退回一幅素描... 」";
  --quote-bg: rgba(255, 255, 255, 0.90); 

  /* 文艺句子位置与距离 */
  --user-quote-top: 135px;     
  --user-quote-left: 10px;     
  --user-msg-margin: 90px;     

  --char-quote-top: 135px;     
  --char-quote-right: 0px;    
  --char-msg-margin: 60px;     

  /* --- 4. 🕰️时间、楼层、字数 (绝对固定版) --- */
  --stats-width: 80px;        
  --stats-height: 18px;        
  --stats-edge-margin: 5px;    
  --stats-gap: 2px; /* 三个标签之间的缝隙，绝不拉伸 */

  /* 上下移动控制 (调节这个数值，整个模块一起移动) */
  --user-stats-top: 15px; 
  --char-stats-top: 15px; 

  /* --- 5. ✨ 底部横线 (User/Char 独立设置) ✨ --- */
  --user-bottom-divider-text: "✧⋆─┈─⋆✧─┈─⋆✧"; 
  --char-bottom-divider-text: "❆┈┈┈⋆✦⋆┈┈┈❆"; 

  --msg-padding-left: 10px;
  --msg-padding-right: 10px;   
  --msg-text-max-width: 100%;  

  /* 正文【上推】距离控制 */
  --user-msg-padding-top: 0px; 
  --char-msg-padding-top: 20px; 

  /* 正文【下拉】距离控制 */
  --user-msg-padding-bottom: 60px; 
  --char-msg-padding-bottom: 100px; 

  /* 底部横线的高度位置 */
  --user-divider-bottom: 25px; 
  --char-divider-bottom: 50px; 

  /* --- 6. 杂项 --- */
  --top-icon-color: var(--SmartThemeBodyColor); 
  --bottom-icon-color: var(--SmartThemeBodyColor); 
  --tc-font-size: 14px; 

  /* ========================================================= */
  /* ✨ 高阶定位与延伸控制区 ✨ */
  /* ========================================================= */

  /* --- 7. 头像与名字的自由移动 --- */
  --user-avatar-x: -20px;       
  --user-avatar-y: 20px;        
  --user-name-x: -20px;         
  --user-name-y: -135px;          

  --char-avatar-x: 20px;        
  --char-avatar-y: 20px;        
  --char-name-x: 18px;        
  --char-name-y: -105px;          

  /* --- 8. 卡片大框的独立左右延伸控制 --- */
  --mes-margin-left: 5px;     
  --mes-margin-right: 0px;    
  --user-msg-shift-x: 0px;     
  --char-msg-shift-x: 0px;     

  /* --- 9.  编辑功能键位置   --- */
  /* User 按钮位置 (头像在左，按键在右) */
  --user-edit-btn-top: -72px;         
  --user-edit-btn-left: auto;       
  --user-edit-btn-right: 0px; 

  /* Char 按钮位置 (头像在右，按键在左)  */
  --char-edit-btn-top: -50px;         
  --char-edit-btn-left: -5px;     
  --char-edit-btn-right: auto; 
}
/* ========================================================= */

/* === 二、底层重置与字体应用 === */
body { 
  background-color: transparent !important; 
  font-family: "Huiwen-mincho", serif !important; 
  line-height: 1.5 !important;
  font-weight: normal !important; 
}

#chat {
  background-color: transparent !important; 
  backdrop-filter: none !important; 
  -webkit-backdrop-filter: none !important;
  padding-bottom: 50px !important; 
}

#top-settings-holder .drawer-icon::before { color: var(--top-icon-color) !important; }
#send_form [class*="fa-"]::before {
  font-family: "Font Awesome 6 Free", sans-serif !important;
  color: var(--bottom-icon-color) !important;
  font-weight: 900;
}

.drawer-content, 
#table_drawer_content, 
.options-content,
.popup, 
#extensions_popup, 
#chat_and_input_extensions_popup,
.list-group {
  background-color: color-mix(in srgb, var(--SmartThemeBlurTintColor) 95%, #1a1a1a) !important;
  background-image: none !important;
  backdrop-filter: blur(15px) !important;
  border: 1px solid rgba(150, 150, 150, 0.3) !important;
}

/* 隐藏QRby十二老师 */
#send_form:hover #qr--bar {
    height: 35px;
    transition: all 0.5s ease;
}
#qr--bar {
    height: 0.5px;
}

/* === 三、统一大框 === */
.mes {
  display: flex !important;
  flex-direction: column !important;
  width: calc(100% - var(--mes-margin-left) - var(--mes-margin-right)) !important; 
  margin-top: var(--mes-margin-top) !important; 
  margin-bottom: 30px !important;
  margin-left: var(--mes-margin-left) !important;  
  margin-right: var(--mes-margin-right) !important; 
  border: 1px solid rgba(150, 150, 150, 0.2) !important;
  border-radius: 16px !important; 
  position: relative;
  isolation: isolate; 
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  box-sizing: border-box;
}
.mes[is_user="false"] { 
  background-color: color-mix(in srgb, var(--SmartThemeBotMesBlurTintColor) var(--char-card-opacity), transparent) !important; 
  backdrop-filter: blur(var(--card-blur)) !important;
  -webkit-backdrop-filter: blur(var(--card-blur)) !important;
}
.mes[is_user="true"] { 
  background-color: color-mix(in srgb, var(--SmartThemeUserMesBlurTintColor) var(--user-card-opacity), transparent) !important; 
  backdrop-filter: blur(var(--card-blur)) !important;
  -webkit-backdrop-filter: blur(var(--card-blur)) !important;
}
.mes::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: var(--banner-height); 
  background-size: cover;
  background-position: center;
  border-radius: 16px 16px 0 0; 
  z-index: -1; 
  border-bottom: 1px solid rgba(0,0,0,0.1);
}
.mes[is_user="true"]::before { background-image: var(--user-big-image); }
.mes[is_user="false"]::before { background-image: var(--char-big-image); }
/* 单独让 Char 背景清晰 */
.mes[is_user="false"] {
  backdrop-filter: blur(0px) !important;
  -webkit-backdrop-filter: blur(0px) !important;
}
/* === 四、头像、名字、统计与文艺句子  === */
.mesAvatarWrapper {
  display: grid !important; 
  position: relative;
  width: 100%;
  box-sizing: border-box;
  margin-top: 110px; 
  min-height: var(--avatar-size) !important; 
  z-index: 2;
}
/* 头像防坍塌 */
.mes .avatar { 
  position: relative; z-index: 3; align-self: flex-start; 
  display: block !important; visibility: visible !important; opacity: 1 !important; 
}
.mes[is_user="true"] .avatar { transform: translate(var(--user-avatar-x), var(--user-avatar-y)); }
.mes[is_user="false"] .avatar { transform: translate(var(--char-avatar-x), var(--char-avatar-y)); }
.mes .avatar img {
  width: var(--avatar-size) !important; 
  height: var(--avatar-size) !important;
  border-radius: 50% !important;
  border: 3px solid rgba(255,255,255,0.95) !important;
  box-shadow: 0 4px 10px rgba(0,0,0,0.2);
}
/* 名字防挤压截断修复 (已更正类名为 .name_text) */
.mes .name_text {
  position: absolute !important;
  z-index: 99 !important; 
  background: transparent !important;
  border: none !important;
  font-size: 15px !important;
  font-weight: bold;
  color: var(--SmartThemeBodyColor) !important;
  text-shadow: 0 1px 4px rgba(255, 255, 255, 0.9); 
  padding: 0 8px;
  white-space: nowrap !important; 
  font-family: "Huiwen-mincho", serif !important; 
  /* 名字防超长溢出 */
  max-width: 180px; 
  overflow: hidden;
  text-overflow: ellipsis;
  display: block !important; 
  visibility: visible !important; 
  opacity: 1 !important; 
}
.mes[is_user="true"] .name_text { 
  top: 35px; left: calc(15px + var(--avatar-size)); 
  transform: translate(var(--user-name-x), var(--user-name-y)); 
}
.mes[is_user="false"] .name_text { 
  top: 35px; right: calc(15px + var(--avatar-size)); 
  transform: translate(var(--char-name-x), var(--char-name-y)); 
}
/* 统计标签基础设定 (定位防拉伸) */
.mes .mesIDDisplay, .mes .mes_timer, .mes .tokenCounterDisplay {
  position: absolute !important;
  display: flex !important;
  justify-content: center;
  align-items: center;
  z-index: 3;
  padding: 0px !important;
  height: var(--stats-height) !important; 
  width: var(--stats-width) !important; 
  border-radius: 0px !important; 
  font-size: 11px !important;
  color: #fff !important; 
  border: none !important; 
  margin: 0 !important; 
  box-sizing: border-box;
  opacity: 1 !important; 
  box-shadow: none !important;
}
/* 文艺句子设定 */
.mesAvatarWrapper::after {
  position: absolute;
  padding: 4px 14px;
  background: var(--quote-bg);
  border-radius: 4px;
  font-size: var(--quote-font-size);
  color: #333;
  font-style: italic !important; 
  z-index: 3;
  box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  transform: skewX(-12deg); 
  font-family: "Huiwen-mincho", serif !important; 
}
/* === 五、排版网格及统计坐标 === */
/* User 侧网格 */
.mes[is_user="true"] .mesAvatarWrapper {
  grid-template-columns: var(--avatar-size) 1fr; 
  padding-left: 15px; 
  margin-bottom: var(--user-msg-margin); 
}
.mes[is_user="true"] .avatar { grid-column: 1; }
.mes[is_user="true"] .mesAvatarWrapper::after {
  content: var(--user-quote-text); 
  top: var(--user-quote-top); 
  left: var(--user-quote-left);
}
/* Char 侧网格 */
.mes[is_user="false"] .mesAvatarWrapper {
  grid-template-columns: 1fr var(--avatar-size); 
  padding-right: 15px; 
  margin-bottom: var(--char-msg-margin); 
}
.mes[is_user="false"] .avatar { grid-column: 2; }
.mes[is_user="false"] .mesAvatarWrapper::after {
  content: var(--char-quote-text); 
  top: var(--char-quote-top);
  right: var(--char-quote-right); 
}
/* 时间楼层字数坐标锁定  */
/* User (右侧两项) */
.mes[is_user="true"] .mes_timer { display: none !important; } 
.mes[is_user="true"] .mesIDDisplay { 
  right: var(--stats-edge-margin); 
  top: var(--user-stats-top); 
  background-color: #1a1a1a !important; 
} 
.mes[is_user="true"] .tokenCounterDisplay { 
  right: var(--stats-edge-margin); 
  top: calc(var(--user-stats-top) + var(--stats-height) + var(--stats-gap)); 
  background-color: #7a7a7a !important; 
}
/* Char (左侧三项) */
.mes[is_user="false"] .mesIDDisplay { 
  left: var(--stats-edge-margin); 
  top: var(--char-stats-top); 
  background-color: #1a1a1a !important; 
} 
.mes[is_user="false"] .mes_timer { 
  left: var(--stats-edge-margin); 
  top: calc(var(--char-stats-top) + var(--stats-height) + var(--stats-gap)); 
  background-color: #7a7a7a !important; 
} 
.mes[is_user="false"] .tokenCounterDisplay { 
  left: var(--stats-edge-margin); 
  top: calc(var(--char-stats-top) + (var(--stats-height) + var(--stats-gap)) * 2); 
  background-color: #1a1a1a !important; 
}
/* === 六、消息内容区 === */
.mes_block {
  background-color: transparent !important; 
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  padding-right: var(--msg-padding-right) !important;
  padding-left: var(--msg-padding-left) !important;
  position: relative;
  overflow: visible !important; 
}
.mes[is_user="true"] .mes_block { 
  padding-top: var(--user-msg-padding-top) !important; 
  padding-bottom: var(--user-msg-padding-bottom) !important;
  transform: translateX(var(--user-msg-shift-x)); 
}
.mes[is_user="false"] .mes_block { 
  padding-top: var(--char-msg-padding-top) !important; 
  padding-bottom: var(--char-msg-padding-bottom) !important;
  transform: translateX(var(--char-msg-shift-x)); 
}
.mes_text {
  width: 100% !important;
  max-width: var(--msg-text-max-width) !important;
  margin: 0 auto !important; 
  padding: 0 !important;
  display: block !important;
  box-sizing: border-box !important;
  /* 单独控制正文字体大小 */
  font-size: 15px !important; 
}
.mes_text p {
  width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  word-break: break-word; 
}
/* === 文字样式优化 === */
.mes_text em {
  color: var(--SmartThemeBodyColor) !important; 
  font-style: italic !important;
  background-color: color-mix(in srgb, var(--SmartThemeEmColor) 35%, var(--SmartThemeBlurTintColor)) !important; 
  border-left: 3px solid var(--SmartThemeEmColor) !important;
  border-bottom: 1px solid color-mix(in srgb, var(--SmartThemeEmColor) 50%, transparent) !important;
  padding: 2px 8px;
  border-radius: 2px 6px 6px 2px;
}
.mes_text blockquote {
  color: #4a5c6b; 
  border-left: 4px solid #8ba8be; 
  background: linear-gradient(to right, rgba(255,255,255,0.6), transparent);
  padding: 8px 12px;
  margin: 8px 0;
  border-radius: 0 6px 6px 0;
  font-style: italic;
}
/* === 底部分割线独立控制 === */
.mes_block::after {
  display: block;
  text-align: center;
  color: var(--SmartThemeBodyColor);
  opacity: 0.4;
  position: absolute;
  left: 0; right: 0;
  font-size: 14px;
}
.mes[is_user="true"] .mes_block::after { 
  content: var(--user-bottom-divider-text);
  bottom: var(--user-divider-bottom); 
}
.mes[is_user="false"] .mes_block::after { 
  content: var(--char-bottom-divider-text);
  bottom: var(--char-divider-bottom); 
}
/* === 编辑/删除功能键 === */
.mes_buttons {
  position: absolute !important;
  display: flex !important;
  flex-direction: row !important;
  background: rgba(0,0,0,0.1) !important; 
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.2) !important;
  box-shadow: none !important;
  opacity: 0.6 !important; 
  transition: 0.2s;
  z-index: 10;
}
.mes[is_user="true"] .mes_buttons {
  top: var(--user-edit-btn-top) !important;
  left: var(--user-edit-btn-left) !important;
  right: var(--user-edit-btn-right) !important;
}
.mes[is_user="false"] .mes_buttons {
  top: var(--char-edit-btn-top) !important;
  left: var(--char-edit-btn-left) !important;
  right: var(--char-edit-btn-right) !important;
}
/* 防位移代码： */
.mes_buttons > * { order: 5; } 
.mes_buttons .swipe_left, 
.mes_buttons .swipe_info, 
.mes_buttons .swipe_right { order: 99 !important; }
.mes_buttons .fa-solid { color: var(--SmartThemeBodyColor) !important; }
.mes_block:hover .mes_buttons { opacity: 1 !important; background: rgba(0,0,0,0.2) !important; }
/* ===  七、思维链 === */
.mes_reasoning_summary {
  list-style: none !important; 
  cursor: pointer;
}
.mes_reasoning_header {
  background-color: transparent !important; 
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 6px 15px !important; 
  border-radius: 6px !important; 
  display: inline-flex !important; 
  align-items: center;
}
.mes_reasoning_header_title, .mes_reasoning_arrow { font-size: 0 !important; }
.mes_reasoning_arrow {
  margin-right: -10px !important; 
  display: flex;
  align-items: center;
}
.mes_reasoning_arrow::before {
  content: '❆'; 
  font-size: 14px !important; 
  color: #8ba8be !important; 
  display: inline-block; 
  transition: transform 0.3s ease;
}
details[open] .mes_reasoning_arrow::before { transform: rotate(90deg); }
.mes_reasoning_header_title::before {
  content: '雪正在落下...'; 
  font-size: 16px !important; 
  color: #8ba8be !important; 
  font-weight: bold; 
  font-style: italic;
}
.mes_reasoning_summary:hover .mes_reasoning_header_title::before,
.mes_reasoning_summary:hover .mes_reasoning_arrow::before {
  color: #a9c6dc !important; 
}
.mes_reasoning {
  max-width: none !important; 
  width: calc(100% + 20px) !important; 
  box-sizing: border-box !important;
  margin-top: 10px; 
  padding: 12px 16px;
  background-color: color-mix(in srgb, var(--SmartThemeBlurTintColor) 20%, transparent);
  border-left: 3px solid #8ba8be; 
  border-radius: 0 6px 6px 0; 
  color: var(--SmartThemeBodyColor); 
  font-family: inherit; 
  font-size: 13px;
  line-height: 1.8;
}
/* === 八、正则+脚本易读+防误触 === */
#saved_regex_scripts, #saved_scoped_scripts, #saved_preset_scripts, #global-script-list, #character-script-list {
  margin-right: 80px !important;
}
.regex-script-label.flex-container, .flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 5px 10px; 
  border-radius: 8px; 
  margin-bottom: 5px; 
  background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 90%, transparent) !important; 
  border: 1px solid rgba(150, 150, 150, 0.4) !important; 
}
.regex-script-label.flex-container .regex_script_name, .script-item .script-item-name {
  flex-basis: 100%;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  word-break: break-word; 
  font-weight: bold;
  font-size: 1.05em;
}
.regex-script-label.flex-container > .flex-container.flexnowrap, .script-item .script-item-control {
  width: 100%; 
  justify-content: flex-start; 
}
/* === SillyTavern 浅色主题 - 灰色元素修复byLuminouk老师 === */
/* --- 1. 扩展面板/设置区的按钮和标题 (例如：快速提示词编辑, 实用提示词) --- */
.inline-drawer-toggle,
.standoutHeader,
.extension_button,
#user-settings-block h4,
.inline-drawer-header {
    /* 关键！强制移除默认的灰色渐变背景 */
    background-image: none !important; 
}
/* 鼠标悬停时的样式 */
.inline-drawer-toggle:hover,
.extension_button:hover {
    /* 在这里修改鼠标悬停时的边框颜色 */
    border-color: #949292 !important; /* 灰色边框 */
}
/* 强效锁死输入框字体，防止斜杠命令导致掉字体byhy老师 */
#send_textarea, 
#send_textarea:focus,
#send_textarea.slash-command {
    font-family: "Huiwen-mincho", 'PingFang SC', sans-serif !important;
}
/* 通知弹窗美化byDeleted User老师 */
.toast {
  background-color: #F5F5F5 !important;
  color: #000000 !important;
}
/* === 提示词预设管理器 (开启前/开启后) 颜色控制 === */

/* --- 1. 【未开启】(Disabled) 状态 --- */
/* 未开启的底色和边框 */
#completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    background-color: rgba(192, 192, 192, 0.15) !important; /* 浅灰色背景 */
    border: 1px solid rgba(150, 150, 150, 0.3) !important; /* 浅灰色边框 */
    border-radius: 6px !important;
    transition: all 0.3s ease !important;
}

/* 未开启的文字和右侧“查看”小图标的颜色 */
#completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #696E7A !important; /* 深灰色文字 */
}
/* --- 2. 【已开启】(Enabled) 状态 --- */
/* 已开启的底色和边框 */
#completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    background-color: #F5F5F5 !important;
    border: 1px solid #A9A9A9 !important;
    border-radius: 6px !important;
    transition: all 0.3s ease !important;
}

/* 已开启的文字 */
#completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-inspect-action {
    color: #000000 !important; /* 纯白色文字 */
    font-weight: bold !important; /* 字体加粗 */
}
